import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:block_puzzle/features/settings/app_settings.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

/// Short sound effects (generated by `tool/generate_sounds.dart`).
///
/// Fill and cross sounds climb a pentatonic ladder: pass a growing `step`
/// while the player keeps dragging and the pitch gets higher and thinner.
/// Every call is fire-and-forget and never throws, so a missing audio
/// backend (tests, unsupported platform) just means silence.
///
/// Each sound owns one player whose source is set once; playing it again
/// is `stop` + `resume`. Swapping sources on a few shared players broke on
/// Android low-latency mode (SoundPool never reports completion, so a
/// player stays "playing" and later plays resume a finished stream — the
/// sound goes silent) and leaked SoundPool bookkeeping on every swap.
class SoundService {
  SoundService();

  static const ladderSize = 15;

  /// The same sound retriggered faster than this is dropped, so a fast drag
  /// cannot queue up more platform calls than the device can play.
  static const minRetrigger = Duration(milliseconds: 35);

  bool enabled = true;

  final _voices = <String, _Voice>{};
  var _disposed = false;
  Future<void>? _setup;

  static const _volumes = {
    'fill': 0.8,
    'cross': 0.55,
    'mistake': 0.9,
    'line': 0.9,
    'win': 1.0,
    'combo': 0.9,
    'hint': 0.8,
  };

  static List<String> get _allAssets => [
    for (var i = 0; i < ladderSize; i++) ...[
      _path('fill', i),
      _path('cross', i),
    ],
    for (final name in ['mistake', 'line', 'win', 'hint', 'combo'])
      'audio/$name.wav',
  ];

  /// Prepares every player so the first play has no delay.
  Future<void> warmUp() async {
    for (final asset in _allAssets) {
      if (_disposed) return;
      _voice(asset);
    }
    await _context;
  }

  /// Players are created only after the shared audio context is set.
  Future<void> get _context => _setup ??= _setContext();

  static Future<void> _setContext() async {
    try {
      // Sound effects must not grab audio focus (that pauses the player's
      // music and costs a system call per play).
      await AudioPlayer.global.setAudioContext(
        AudioContextConfig(
          focus: AudioContextConfigFocus.mixWithOthers,
        ).build(),
      );
    } on Object {
      // Silent fallback.
    }
  }

  static String _path(String name, int step) =>
      'audio/${name}_${step.clamp(0, ladderSize - 1).toString().padLeft(2, '0')}'
      '.wav';

  void fill(int step) => _play(_path('fill', step));
  void cross(int step) => _play(_path('cross', step));
  void mistake() => _play('audio/mistake.wav');
  void line() => _play('audio/line.wav');
  void win() => _play('audio/win.wav');
  void combo() => _play('audio/combo.wav');
  void hint() => _play('audio/hint.wav');

  void _play(String asset) {
    if (!enabled || _disposed) return;
    _voice(asset).trigger();
  }

  _Voice _voice(String asset) => _voices.putIfAbsent(
    asset,
    () => _Voice(asset, _volumeOf(asset), _context),
  );

  static double _volumeOf(String asset) {
    final name = asset.split('/').last.split('.').first.split('_').first;
    return _volumes[name] ?? 0.8;
  }

  void dispose() {
    _disposed = true;
    for (final voice in _voices.values) {
      voice.dispose();
    }
    _voices.clear();
  }
}

/// One sound with its own player. Calls to the player are chained so a
/// stop never overtakes the resume before it.
class _Voice {
  _Voice(String asset, double volume, Future<void> ready) {
    _chain = ready.then(
      (_) => _run(() async {
        final player = AudioPlayer();
        _player = player;
        await player.setPlayerMode(PlayerMode.lowLatency);
        await player.setReleaseMode(ReleaseMode.stop);
        await player.setVolume(volume);
        await player.setSource(AssetSource(asset));
      }),
    );
  }

  AudioPlayer? _player;
  late Future<void> _chain;
  DateTime _lastStart = DateTime.fromMillisecondsSinceEpoch(0);
  var _queued = false;

  void trigger() {
    final now = DateTime.now();
    if (_queued || now.difference(_lastStart) < SoundService.minRetrigger) {
      return;
    }
    _lastStart = now;
    _queued = true;
    _chain = _chain.then(
      (_) => _run(() async {
        _queued = false;
        final player = _player;
        if (player == null) return;
        await player.stop();
        await player.resume();
      }),
    );
  }

  static Future<void> _run(Future<void> Function() body) async {
    try {
      await body();
    } on Object {
      // Silent fallback: a broken voice just stays quiet.
    }
  }

  void dispose() {
    final player = _player;
    _player = null;
    if (player != null) unawaited(_run(player.dispose));
  }
}

final soundServiceProvider = Provider<SoundService>((ref) {
  final service = SoundService();
  unawaited(service.warmUp());
  ref
    ..listen(
      settingsProvider.select((s) => s.sound),
      (_, on) => service.enabled = on,
      fireImmediately: true,
    )
    ..onDispose(service.dispose);
  return service;
});
